import pandas as pd,numpy as np
from common import *
d=pd.read_csv(R/'results/reference_checks.csv');p=pd.read_csv(R/'results/empty_pair_comparisons.csv');c=pd.read_csv(R/'results/cross_record_prediction.csv');n=pd.read_csv(R/'results/empty_null_spectral_changes.csv');s=pd.read_csv(R/'results/source_audit.csv')
sel=load(R/'results/development_selection.json')['selected_variant'];z=d[d.variant==sel];h=z[~z['index'].isin(CFG['empty_development'])];pair=p[(p.variant=='full')&(p.comparison=='E1_E3')]
out=dict(selected_reference=sel,reference_states=len(z),reference_passes=int(z.actual_model_applied.sum()),holdout_states=len(h),holdout_passes=int(h.actual_model_applied.sum()),holdout_future_corr_median=float(h.predicted_corr_C.median()),holdout_delay_failures=int((h.chain_delay_p90_ns>5).sum()),holdout_phase_failures=int((h.chain_phase_p90_deg>15).sum()),holdout_prefix_corr_failures=int((h.prefix_predictive_correlation<.9).sum()),cross_record_checks=len(c),cross_record_gate_passes=int(c.common_pass.sum()),cross_record_future_corr_median=float(c.future_pred_corr_C_candidate.median()),same_session_cross_capture_pairs=len(pair),pair_medians={k:float(pair[k].median()) for k in ['spatial_distance','amplitude_distance','covariance_distance','pair_phase_median_deg']},repeatability_pass_counts={k:int(pair[k+'_pass'].sum()) for k in ['spatial_distance','amplitude_distance','covariance_distance']},null_counts=n.groupby('comparison').agg(pairs=('state','size'),exceedances=('threshold_exceeded','sum')).reset_index().to_dict('records'),invariant_B_max=float(d.B_cov_change.max()),actual_C_cov_max=float(d.C_cov_change.max()),same_frequency_spatial_change_max=float(d.spatial_change.max()),timestamp_shift_max_ns=int(s.relative_timestamp_shift_max_error_ns.max()),source_dates_used=False,occupied_empty_relation='different hardware sessions confirmed by user')
out['background_recovery_gate_pass']=bool(out['holdout_passes']>=CFG['minimum_valid_states_fraction']*len(h) and out['cross_record_gate_passes']>=CFG['minimum_valid_states_fraction']*len(c) and pair.spatial_distance_pass.mean()>=CFG['minimum_valid_states_fraction'] and pair.covariance_distance_pass.mean()>=CFG['minimum_valid_states_fraction'])
out['stage_decisions']=dict(empty_null_diagnostic='completed using uncalibrated normalized MUSIC changes',background_whitening='not entered: no validated stable background reference' if not out['background_recovery_gate_pass'] else 'requires further validation',human_new_processing='not entered: empty reference gate failed and cross-session transfer unverified',existing_human_spectra='reuse all 39 run results with uncalibrated labels',localization='not entered: no verified human path/direct path/fixed response calibration')
dump(R/'results/decision.json',out)
